import json,os,subprocess,sys,time
from pathlib import Path
from scripts import run_causal_source_capture as capture
from experiments.reports.workflow_mix_20261029.review_burst import complete_work
registration, destination, output = map(Path,sys.argv[1:4])
commands=json.loads(sys.argv[4])
state={'status':'waiting_complete_Full','process':capture.reservation.process(os.getpid()),'GPU_followup_registered':False,'steps':[],'source_commit':sys.argv[5]}
def publish():
 state['checked_at']=capture.reservation.now().isoformat()
 capture.reservation.write_json(destination,state)
try:
 deadline=time.monotonic()+4*3600
 while True:
  current=capture.load(registration.with_suffix('.state.json'))
  if current.get('status')=='stopped_for_investigation':
   raise RuntimeError('Full stopped; preserve its incomplete work: '+str(current.get('error')))
  if current.get('status')=='collected_performance_review_pending' and complete_work(registration) is not None:
   break
  if time.monotonic()>deadline: raise TimeoutError('complete control review deadline exceeded')
  publish();time.sleep(10.)
 output.mkdir(parents=True,exist_ok=False)
 for name,command in commands:
  state.update(status='reviewing_complete_Full',current_step=name);publish()
  child=subprocess.Popen(command)
  while child.poll() is None:
   publish()
   try: child.wait(timeout=30.)
   except subprocess.TimeoutExpired: pass
  state['steps'].append({'name':name,'returncode':child.returncode})
  if child.returncode: raise RuntimeError(name+' failed')
 state['status']='complete_requires_workload_and_oracle_decision'
 state['formal_workload_qualified']=False
except BaseException as error:
 state.update(status='stopped_preserve_corrected_review',error=repr(error))
state['finished_at']=capture.reservation.now().isoformat();publish()

